(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"punctuation-commas-series":{"title":"Commas in a Series","topic":"Punctuation","questions":[{"id":"punctuation-commas-series-q0001","version":3,"contentHash":"sha256:1834fbb70ed1c65211abe661140b46aa7e809f3464c9e0a68a244af28368d067","question":"Which sentence uses commas correctly in a series?","choices":["I bought apples oranges and bananas.","I bought apples, oranges and bananas.","I bought apples, oranges, and bananas.","I bought, apples, oranges, and bananas."],"correct":2,"explanation":{"correct":"Answer: I bought apples, oranges, and bananas. When listing three or more items, place a comma after every item except the last one. Using an Oxford comma before the 'and' is a standard way to keep list items clear.","incorrect":[{"choice":"I bought apples oranges and bananas.","category":"missing punctuation","reason":"This sentence is confusing because the items are run together. Commas are needed to show where one item ends and the next begins."},{"choice":"I bought apples, oranges and bananas.","category":"missing Oxford comma","reason":"While some styles allow this, it is safer to include the comma before the final 'and' to clearly separate the last two items in your list."},"",{"choice":"I bought, apples, oranges, and bananas.","category":"misplaced comma","reason":"You should not place a comma between the verb 'bought' and the first item in the list. The list starts after the verb, not before."}]},"studyAid":{"definition":"When listing three or more items, use a comma after each item except for the final one. You may also place a comma before the 'and' to ensure the list is easy to read.","example":"Correct: I need pencils, paper, and erasers. Incorrect: I need pencils paper and erasers.","strategyClue":"Imagine you are pausing to take a breath for each item in the list. Place your commas exactly where those natural pauses occur, making sure not to put a comma between the action word and the first item.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":1,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0002","version":3,"contentHash":"sha256:6b679753d6f1a3512c574e20dcdf311c7afe4dc02eb0ebda0f675951cf808748","question":"Which sentence is correct?","choices":["My favorite colors are red blue and green.","My favorite colors are red, blue and green.","My favorite colors are red, blue, and green.","My favorite colors are, red, blue, and green."],"correct":2,"explanation":{"correct":"Answer: My favorite colors are red, blue, and green. When listing three or more items in a series, you must place a comma after each item except the last one.","incorrect":[{"choice":"My favorite colors are red blue and green.","category":"missing commas in series","reason":"When you list multiple items, you need commas to separate them so the reader knows where one color ends and the next begins."},{"choice":"My favorite colors are red, blue and green.","category":"missing Oxford comma","reason":"While this is sometimes used in informal writing, standard academic style requires a comma before the 'and' in a list of three or more items to keep the list clear."},"",{"choice":"My favorite colors are, red, blue, and green.","category":"incorrect comma placement","reason":"You should not place a comma immediately after the verb 'are'. Commas are used to separate items in the list, not to separate the verb from the list itself."}]},"studyAid":{"definition":"Use commas to separate three or more words or phrases in a list. Put a comma after every item except for the very last one.","example":"I need paper, pencils, and erasers. We saw lions, tigers, and bears.","strategyClue":"Read the sentence out loud and notice where your voice naturally pauses between the items. Place your commas at those specific spots, but remember to always include one before the final conjunction.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":2,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0003","version":3,"contentHash":"sha256:76f5bd6d0a3a966cc981d549c5b948d1e83a11ea1e0d9c535c54314fd861d175","question":"Which sentence incorrectly uses commas?","choices":["She likes to swim, hike, and bike.","She likes to swim hike and bike.","She likes to swim, hike and bike.","She likes, to swim, hike, and bike."],"correct":3,"explanation":{"correct":"Answer: She likes, to swim, hike, and bike. This sentence is incorrect because it uses a comma between the verb 'likes' and the object 'to swim'. Commas should be used to separate items in a list, not to break apart a verb from its object.","incorrect":[{"choice":"She likes to swim, hike, and bike.","category":"correct sentence structure","reason":"This sentence is actually correct! It uses commas to properly separate the items in a list of three actions."},{"choice":"She likes to swim hike and bike.","category":"missing list commas","reason":"When listing three or more items, you need commas to separate them so the reader knows where one action ends and the next begins."},{"choice":"She likes to swim, hike and bike.","category":"optional serial comma","reason":"While some styles omit the final comma before 'and', this is generally considered a correct way to punctuate a list, unlike the first choice which breaks the main verb from the rest of the sentence."},""]},"studyAid":{"definition":"Use commas to separate items in a list of three or more things or actions, but do not place a comma between a verb and the objects that follow it.","example":"Correct: I eat apples, bananas, and pears. Incorrect: I eat, apples, bananas and pears.","strategyClue":"Read the sentence aloud. If your voice pauses naturally to separate items in a list, a comma belongs there; if a comma splits a verb from its action, remove it.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-commas-series","sequence":3,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0004","version":3,"contentHash":"sha256:31fd3ca381fc78164d06fcfedb8f25385e436b3327d0ff664341c421eb5d9439","question":"Where do commas go: 'The flag is red white and blue'","choices":["The flag is red, white and blue.","The flag is red, white, and blue.","The flag is, red, white, and blue.","The flag is red white, and blue."],"correct":1,"explanation":{"correct":"Answer: The flag is red, white, and blue. In a series of three or more items, place a comma after every item except for the last one.","incorrect":[{"choice":"The flag is red, white and blue.","category":"missing oxford comma","reason":"While this is sometimes acceptable, using the Oxford comma after 'white' is standard practice to ensure every item in your list is clearly separated."},"",{"choice":"The flag is, red, white, and blue.","category":"misplaced comma","reason":"Do not put a comma between the verb 'is' and the first item in your list. Commas should only separate the items themselves."},{"choice":"The flag is red white, and blue.","category":"missing separator","reason":"You missed a comma after 'red'. You must place a comma between every item in a list of three or more."}]},"studyAid":{"definition":"When listing three or more items in a row, use commas to separate them from each other.","example":"Correct: I bought apples, oranges, and pears. Incorrect: I bought apples oranges and pears.","strategyClue":"Count the items in your list. Once you identify the three objects, check that there is a comma placed immediately after each of the first two items.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":4,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0005","version":3,"contentHash":"sha256:2443a59173a1bb3bd066851ccd8c1ba67b34be6f8c2359b110d0da0f1ac2f100","question":"Which sentence is correct?","choices":["We packed sandwiches juice and cookies.","We packed sandwiches, juice, and cookies.","We packed sandwiches juice, and cookies.","We packed, sandwiches, juice, and cookies."],"correct":1,"explanation":{"correct":"Answer: We packed sandwiches, juice, and cookies. Use commas to separate three or more items in a list so the reader knows where one item ends and the next begins.","incorrect":[{"choice":"We packed sandwiches juice and cookies.","category":"missing comma punctuation","reason":"This sentence is missing commas between the items. Without them, the nouns run together and become confusing to read."},"",{"choice":"We packed sandwiches juice, and cookies.","category":"incomplete list punctuation","reason":"You must place a comma between every item in a list of three or more. This version misses the comma between 'sandwiches' and 'juice'."},{"choice":"We packed, sandwiches, juice, and cookies.","category":"incorrect comma placement","reason":"You should not place a comma between the verb ('packed') and the first item in the list ('sandwiches'). Commas only separate the items themselves."}]},"studyAid":{"definition":"When listing three or more things in a row, use a comma after each item except the last one.","example":"Correct: I like cats, dogs, and birds. Incorrect: I like cats dogs and birds.","strategyClue":"Imagine you are saying the list out loud and pausing briefly after each item. Every place you naturally pause to list an object, you need a comma.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":5,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0006","version":3,"contentHash":"sha256:02429ec66763c5ef80f4c59529d0c351687a04e32b5c1222fb76ecacae1987ec","question":"Which uses commas correctly?","choices":["He is smart funny and kind.","He is smart, funny, and kind.","He is smart funny, and kind.","He is, smart, funny, and kind."],"correct":1,"explanation":{"correct":"Answer: He is smart, funny, and kind. When listing three or more items in a series, you must place a comma after each item except the last one.","incorrect":[{"choice":"He is smart funny and kind.","category":"missing list commas","reason":"This sentence ignores all punctuation between the adjectives. Commas are needed to separate each item in the list so the reader knows where one ends and the next begins."},"",{"choice":"He is smart funny, and kind.","category":"incomplete list commas","reason":"This version is missing a comma after 'smart'. You need to separate every item in the list consistently before the final 'and'."},{"choice":"He is, smart, funny, and kind.","category":"incorrect comma placement","reason":"The comma after 'is' is unnecessary because it separates the verb from the list of adjectives. Commas should only go between the items themselves."}]},"studyAid":{"definition":"Use commas to separate three or more items in a list. Put a comma after every item except for the very last one.","example":"I bought apples, oranges, and pears. / She likes running, swimming, and biking.","strategyClue":"Identify the list of items in the sentence and place a comma after each item until you reach the final one joined by the word 'and'.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":6,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0007","version":3,"contentHash":"sha256:b6a6500099ee460c65581ebabd7c8949f0716fef1d038b3332f4bc65d8ff55a9","question":"Which is incorrect?","choices":["I want pizza, salad, or soup.","I want pizza salad, or soup.","I want pizza, salad or soup.","I want, pizza, salad, or soup."],"correct":3,"explanation":{"correct":"Answer: I want, pizza, salad, or soup. This sentence is incorrect because it includes an unnecessary comma between the verb 'want' and the direct objects 'pizza, salad, or soup'. You should not place a comma between a verb and the objects that follow it.","incorrect":[{"choice":"I want pizza, salad, or soup.","category":"correct punctuation","reason":"This is actually the correct way to write the sentence. It uses commas to separate three or more items in a list correctly."},{"choice":"I want pizza salad, or soup.","category":"missing comma","reason":"This choice is missing the comma between 'pizza' and 'salad'. When listing three or more items, you must place a comma after every item except the last one."},{"choice":"I want pizza, salad or soup.","category":"optional comma usage","reason":"While this is often accepted, it is missing the Oxford comma. Using a comma before 'or' makes the list clearer and is standard practice in many writing guides."},""]},"studyAid":{"definition":"When listing three or more items in a sentence, use commas to separate them. Do not place a comma between the verb and the first item of the list.","example":"I bought apples, oranges, and pears. (Correct) / I bought, apples, oranges and pears. (Incorrect)","strategyClue":"Identify the verb in the sentence. Check that no punctuation mark separates the action word from the things being acted upon or requested.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-commas-series","sequence":7,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0008","version":3,"contentHash":"sha256:e2faf54bee051d5822b3d50526fb9f093c2fc4c9f7e80fe3de3f0dab09edc592","question":"Which sentence uses commas correctly with phrases in a series?","choices":["I went to the park the library and the store.","I went to the park, the library, and the store.","I went to the park, the library and the store.","I went, to the park, the library, and the store."],"correct":1,"explanation":{"correct":"Answer: I went to the park, the library, and the store. This sentence correctly uses the Oxford comma before the conjunction 'and' to separate three distinct items in a series.","incorrect":[{"choice":"I went to the park the library and the store.","category":"missing commas in series","reason":"When listing three or more items, you must use commas to separate them so the reader knows where one item ends and the next begins."},"",{"choice":"I went to the park, the library and the store.","category":"missing Oxford comma","reason":"While some styles omit the final comma, including the comma before 'and' is the most accurate way to clearly separate items in a series."},{"choice":"I went, to the park, the library, and the store.","category":"misplaced comma error","reason":"The first comma is incorrect because you should not place a comma between a verb and the phrase that follows it. It unnecessarily breaks the flow of the sentence."}]},"studyAid":{"definition":"When listing three or more items, place a comma after each item except for the very last one. Including a comma before the final 'and' is called the Oxford comma.","example":"Correct: I like red, blue, and green. Incorrect: I like red blue and green.","strategyClue":"Locate every item in the list and look for the conjunction (like 'and' or 'or'). Ensure there is a comma separating each individual item from the others, including one right before the final conjunction.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"punctuation-commas-series","sequence":8,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0009","version":3,"contentHash":"sha256:b69d9c8823abc87e07db7d69cbbb378903ddaac162d2ceadf9eb03455bb4a717","question":"Which sentence is correct?","choices":["For breakfast I had eggs toast and juice.","For breakfast, I had eggs, toast, and juice.","For breakfast I had, eggs, toast, and juice.","For breakfast, I had eggs toast, and juice."],"correct":1,"explanation":{"correct":"Answer: For breakfast, I had eggs, toast, and juice. This sentence correctly uses a comma after the introductory phrase 'For breakfast' and uses commas to separate three or more items in a series.","incorrect":[{"choice":"For breakfast I had eggs toast and juice.","category":"missing comma usage","reason":"This sentence is missing commas. When you list three or more items, you must place commas between them to help the reader know where one item ends and the next begins."},"",{"choice":"For breakfast I had, eggs, toast, and juice.","category":"incorrect comma placement","reason":"You should not place a comma between the verb 'had' and the first item in your list ('eggs'). Commas are for separating list items from each other, not for breaking apart the verb and its objects."},{"choice":"For breakfast, I had eggs toast, and juice.","category":"missing list comma","reason":"You are missing a comma between 'eggs' and 'toast'. In a list of three items, you need a comma after the first item and the second item to clearly group them."}]},"studyAid":{"definition":"Use commas to set off introductory phrases at the start of a sentence and to separate three or more items in a list.","example":"In the morning, I run, swim, and bike. I bought apples, pears, and bananas.","strategyClue":"Read the sentence out loud and listen for natural pauses. Check for a short break after the introduction and a rhythmic pause between every item in your list.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":9,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0010","version":3,"contentHash":"sha256:001e05374f518ced85e37c918756477a36d5ab84ad5b2292331eeddfeea9e195","question":"Which incorrectly places a comma?","choices":["My pets are a dog, a cat, and a fish.","My pets are a dog a cat and a fish.","My pets are a dog, a cat and a fish.","My pets, are a dog, a cat, and a fish."],"correct":3,"explanation":{"correct":"Answer: My pets, are a dog, a cat, and a fish. This sentence is incorrect because it places a comma between the subject 'My pets' and the verb 'are'. You should never place a single comma between a subject and its verb.","incorrect":[{"choice":"My pets are a dog, a cat, and a fish.","category":"correct punctuation usage","reason":"This sentence is actually correctly punctuated. It uses commas to separate items in a list and does not incorrectly separate the subject from the verb."},{"choice":"My pets are a dog a cat and a fish.","category":"missing list commas","reason":"When listing three or more items, you must use commas to separate them so the reader can tell where one item ends and the next begins."},{"choice":"My pets are a dog, a cat and a fish.","category":"acceptable list punctuation","reason":"This is generally considered correct. While the Oxford comma (before 'and') is optional, this sentence does not make the error of placing a comma between the subject and the verb."},""]},"studyAid":{"definition":"Commas are used to separate three or more items in a list, but they should never be used to break apart the subject and the verb of a sentence.","example":"Correct: I bought apples, oranges, and pears. Incorrect: I bought, apples, oranges, and pears.","strategyClue":"Identify the main subject and the verb of the sentence. If a comma appears immediately between them, that is a punctuation error.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-commas-series","sequence":10,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0011","version":3,"contentHash":"sha256:4923349ed4b1a28e7b94b71dfc2cb10925624475435d963393c90be461ee391b","question":"Which sentence is correct?","choices":["She sang danced and laughed.","She sang, danced, and laughed.","She sang danced, and laughed.","She, sang, danced, and laughed."],"correct":1,"explanation":{"correct":"Answer: She sang, danced, and laughed. When listing three or more items in a series, you must place a comma after each item except the last one to separate them clearly.","incorrect":[{"choice":"She sang danced and laughed.","category":"missing commas","reason":"Without commas, the action words run together. You need to separate 'sang', 'danced', and 'laughed' so the reader knows they are three distinct actions."},"",{"choice":"She sang danced, and laughed.","category":"incomplete punctuation","reason":"This choice is missing the comma after 'sang'. Since there are three items in the list, you need a comma after the first action and the second action."},{"choice":"She, sang, danced, and laughed.","category":"unnecessary comma","reason":"The comma after 'She' is incorrect because it separates the subject from the rest of the sentence. Only put commas between the items in the list, not after the subject."}]},"studyAid":{"definition":"When listing three or more items in a series, use commas to separate each item. Place a comma after every item except the last one.","example":"Correct: I bought apples, oranges, and pears. Incorrect: I bought apples oranges and pears.","strategyClue":"Look at the list of actions. Put your finger where each distinct action begins and ends, then place a comma at every natural 'pause' point between those actions.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":11,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0012","version":3,"contentHash":"sha256:8891da051efd6200cfc5eb36a7abeba0cc81be6e298399cdb8959f369d38ebba","question":"Which uses commas correctly?","choices":["At the store we need milk bread and eggs.","At the store, we need milk, bread, and eggs.","At the store we need, milk, bread, and eggs.","At the store, we need milk bread, and eggs."],"correct":1,"explanation":{"correct":"Answer: At the store, we need milk, bread, and eggs. This sentence correctly uses a comma after the introductory phrase 'At the store' and uses commas to separate items in a list, including the oxford comma before 'and'.","incorrect":[{"choice":"At the store we need milk bread and eggs.","category":"missing list commas","reason":"This sentence fails to use commas to separate the items in the list. Commas are needed to tell the reader where one item ends and the next begins."},"",{"choice":"At the store we need, milk, bread, and eggs.","category":"misplaced comma usage","reason":"A comma should not be placed between the verb 'need' and the first item in the list ('milk'). Only separate the items themselves, not the verb from its objects."},{"choice":"At the store, we need milk bread, and eggs.","category":"incomplete list punctuation","reason":"This sentence incorrectly groups 'milk' and 'bread' together without a comma between them. Every item in a list must be clearly separated."}]},"studyAid":{"definition":"Use commas to separate three or more items in a list, and use a comma after an introductory phrase that sets the time or place for the sentence.","example":"I like red, blue, and green. After the game, we went home.","strategyClue":"Read the sentence slowly and count the distinct items being listed; then, check if a short pause is needed after the opening phrase to separate it from the main action.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":12,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0013","version":3,"contentHash":"sha256:07775502d6a9ab5df0cf0ce5b12a9f7c4ec09f0bb71c410c0982a92b73fd4d82","question":"Which sentence is correct?","choices":["I like vanilla chocolate and strawberry ice cream.","I like vanilla, chocolate, and strawberry ice cream.","I like vanilla chocolate, and strawberry ice cream.","I like, vanilla, chocolate, and strawberry ice cream."],"correct":1,"explanation":{"correct":"Answer: I like vanilla, chocolate, and strawberry ice cream. When listing three or more items in a series, you must place a comma after each item except the last one.","incorrect":[{"choice":"I like vanilla chocolate and strawberry ice cream.","category":"missing commas","reason":"This sentence fails to separate the items in the list. Commas are needed to show where one flavor ends and the next begins."},"",{"choice":"I like vanilla chocolate, and strawberry ice cream.","category":"incorrect comma placement","reason":"This misses a comma between 'vanilla' and 'chocolate'. You need to separate all items in a series, not just the last two."},{"choice":"I like, vanilla, chocolate, and strawberry ice cream.","category":"unnecessary comma","reason":"The comma after the verb 'like' is incorrect because it separates the verb from the list of things you enjoy. Only place commas between the items themselves."}]},"studyAid":{"definition":"Use commas to separate three or more items in a list. You should place a comma after every item in the list except for the last one.","example":"Correct: I need pens, paper, and glue. Incorrect: I need pens paper and glue.","strategyClue":"Read the list aloud and pause briefly at each item. Each time you pause to list a new thing, check if there is a comma there to act as a 'stop sign' for the reader.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":13,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0014","version":3,"contentHash":"sha256:0925bbd2ea567b2c88ad6b6bde7044529131b12fe81d0f8d7c0cc5c3228dff22","question":"Which incorrectly uses commas?","choices":["Please bring a pen, paper, and scissors.","Please bring a pen paper and scissors.","Please bring a pen, paper and scissors.","Please, bring a pen, paper, and scissors."],"correct":3,"explanation":{"correct":"Answer: Please, bring a pen, paper, and scissors. This sentence is incorrect because it uses an unnecessary comma after the introductory word 'Please'. When 'Please' starts a request, it does not require a comma unless it is part of a direct address or a distinct interjection.","incorrect":[{"choice":"Please bring a pen, paper, and scissors.","category":"correct punctuation","reason":"This sentence is actually correct! It uses commas to separate items in a series, which is the standard way to list things in English."},{"choice":"Please bring a pen paper and scissors.","category":"missing series commas","reason":"This is incorrect because it is missing the commas needed to separate the items 'pen', 'paper', and 'scissors' in a list."},{"choice":"Please bring a pen, paper and scissors.","category":"Oxford comma usage","reason":"While this is often accepted, it is missing the final comma before 'and' (the Oxford comma), which helps to clearly separate the last two items in the list."},""]},"studyAid":{"definition":"Use commas to separate three or more items in a list. You do not need a comma after a polite opening word like 'Please' unless it is set off from the rest of the sentence.","example":"I need red, blue, and green paint. (Correct) / I need red blue and green paint. (Incorrect)","strategyClue":"Read the sentence aloud. Pause naturally where the commas are placed. If a pause feels forced or unnatural after the first word, that comma is likely unnecessary.","link":"https://www.grammar-monster.com/lessons/commas_in_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-commas-series","sequence":14,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0015","version":3,"contentHash":"sha256:6b37db0096517ed0c89eac0a560985a7db789e91032581be5b3247bdfd2e51f3","question":"Which sentence uses commas correctly in a series with longer items?","choices":["For the project, we need poster board, colored pencils, and a folder with pockets.","For the project we need poster board colored pencils, and a folder with pockets.","For the project, we need poster board, colored pencils and, a folder with pockets.","For the project, we need, poster board, colored pencils, and a folder with pockets."],"correct":0,"studyAid":{"definition":"When listing three or more things, use commas to separate each item in the series. The comma before the 'and' is called the Oxford comma.","example":"I bought apples, oranges, and bananas. She likes to read, write, and draw.","strategyClue":"Read the sentence slowly and count the items being listed. Check that every item is clearly separated from the others by a comma, ending with a comma before the word 'and'.","link":"https://www.grammar-monster.com/lessons/commas_lists.htm","linkText":"Grammar Monster - Commas in Lists"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":15,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"explanation":{"correct":"Answer: For the project, we need poster board, colored pencils, and a folder with pockets. Commas are used to separate three or more items in a list, including before the final 'and' in a series.","incorrect":["",{"choice":"For the project we need poster board colored pencils, and a folder with pockets.","category":"missing commas","reason":"This sentence misses a comma after 'poster board'. Every item in a series should be separated by a comma so the reader can distinguish where one item ends and the next begins."},{"choice":"For the project, we need poster board, colored pencils and, a folder with pockets.","category":"misplaced comma","reason":"The comma should come before the 'and', not after it. Placing the comma after 'and' breaks the flow of the list and separates the conjunction from the final item."},{"choice":"For the project, we need, poster board, colored pencils, and a folder with pockets.","category":"unnecessary comma","reason":"The comma after the word 'need' is incorrect because it separates the verb from the list items. You should only use commas to separate the items themselves, not to set the list apart from the verb."}]}},{"id":"punctuation-commas-series-q0016","version":3,"contentHash":"sha256:2f0b6a513b614564242ca5f940fa98235e5eca76624a29d55d42c1a350537ba9","question":"Which blanks in the paragraph below need punctuation? Trees come in all shapes __A__ and sizes __B__ many trees are popular in landscaping __C__ how many trees are planted __D__ around your school __E__ at our school, each year the fifth grade plants a tree__F__ the trees help beautify our campus __G__","choices":["B, C, E, F, G","B, D, E","A, C, G","C, D, E, G"],"correct":0,"explanation":{"correct":"Answer: B, C, E, F, G. Punctuation is required to separate independent clauses and end sentences. B requires a comma before 'many', C needs a period/question mark structure change, E ends a sentence, F ends a sentence, and G ends a sentence.","incorrect":["",{"choice":"B, D, E","category":"missing sentence markers","reason":"This choice misses important sentence endings at F and G, leaving run-on sentences that make it difficult for the reader to know where one thought stops and another begins."},{"choice":"A, C, G","category":"incorrect comma usage","reason":"Placing punctuation at A breaks up the phrase 'shapes and sizes', which should not be separated. Additionally, this choice omits necessary sentence-ending marks at B and E."},{"choice":"C, D, E, G","category":"incomplete sentence breaks","reason":"This choice incorrectly marks D while failing to identify the necessary comma at B, which is needed to connect the first two independent clauses."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":16,"sourceFile":"Advanced-2_Mechanics and Punctuation.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Punctuation marks like periods, commas, and question marks help organize words into clear sentences and ideas, showing the reader where to pause or stop.","example":"Correct: I love dogs. Do you? Incorrect: I love dogs do you","strategyClue":"Read the paragraph aloud slowly; every time you feel a natural pause or reach the end of a complete thought, check if a punctuation mark is needed there.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0017","version":3,"contentHash":"sha256:7c37c5108eecc1d50dcb7243d42df2ae3041f792d5a32c7cd1eacb77e048c365","question":"Where should commas be placed in this sentence? While they waited __A__ for Santa Claus __B__ m y kids made chocolate chip __C__ cookies __D__ and they made sure __E__ there was plenty of cold milk.","choices":["B, E","A, C, E","B, D","A, C, D"],"correct":2,"explanation":{"correct":"Answer: B, D. A comma is needed at B after the introductory clause 'While they waited for Santa Claus', and at D after the list of items 'chocolate chip cookies' to separate two independent clauses joined by a coordinating conjunction.","incorrect":[{"choice":"B, E","category":"incorrect comma placement","reason":"Adding a comma at E is unnecessary because 'there was plenty of cold milk' is not a separate independent clause that requires a pause, but rather the direct object of the verb 'made sure'."},{"choice":"A, C, E","category":"excessive comma usage","reason":"Placing commas at A or C breaks the flow of the phrases 'waited for' and 'chocolate chip cookies' where no grammatical pause is required."},"",{"choice":"A, C, D","category":"misplaced commas","reason":"The commas at A and C interrupt the natural phrases, making the sentence harder to read, and miss the necessary pause after the introductory clause at B."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":17,"sourceFile":"Advanced-3_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use a comma after an introductory phrase to signal a pause before the main part of the sentence, and before a coordinating conjunction (like 'and', 'but', 'or') when it connects two complete sentences.","example":"After the movie, we went home. I ate a slice of pizza, and my friend ate a burger.","strategyClue":"Read the sentence aloud naturally. Place a comma where you feel a distinct, natural breath or pause, specifically at the end of introductory groups of words or before a joining word that connects two separate full sentences.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0018","version":3,"contentHash":"sha256:214a986cabab71e9d877b8cbf8337b90e36f4ac9580f720105ea965dbede8ba9","question":"In which sentence are the commas correct?","choices":["We went to the store and bought bread, eggs, and milk.","We, went to the store and bought bread eggs and milk.","We went to, the store and, bought bread eggs and milk.","We went, to the, store and bought bread eggs and milk."],"correct":0,"explanation":{"correct":"Answer: We went to the store and bought bread, eggs, and milk. In a series of three or more items, use commas to separate each item. This sentence correctly lists the three groceries with commas between the items.","incorrect":["",{"choice":"We, went to the store and bought bread eggs and milk.","category":"incorrect comma placement","reason":"You should not place a comma between the subject and the verb. 'We' is the subject and 'went' is the verb, so they should not be separated by a comma."},{"choice":"We went to, the store and, bought bread eggs and milk.","category":"incorrect comma placement","reason":"These commas interrupt the flow of the sentence by separating a preposition from its object. Also, a list of items requires commas between the items themselves, not just randomly in the sentence."},{"choice":"We went, to the, store and bought bread eggs and milk.","category":"incorrect comma placement","reason":"Placing commas here breaks apart the phrase 'went to the store'. Commas should be used to separate items in a list, not to break up complete thoughts or phrases."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":18,"sourceFile":"Basic-2_Mechanics and Punctuation.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use commas to separate three or more items in a list. You do not need a comma when you only have two items.","example":"I like cats, dogs, and birds. (List) vs. I like cats and dogs. (No list)","strategyClue":"Look for a list of three or more nouns. Count how many items are being listed and check that a comma follows every item except the very last one.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0019","version":3,"contentHash":"sha256:d26052160475301b4d2c620335ffa4bcdc0fe0a38b4cd0af87ffaf024c7dcbf6","question":"Which sentence uses the comma in the correct place?","choices":["We went to the zoo and we, fed the animals.","We went to the zoo, and we fed the animals.","We went to the zoo and we fed the animals.","We went to the zoo and we fed, the animals."],"correct":1,"explanation":{"correct":"Answer: We went to the zoo, and we fed the animals. When connecting two complete sentences with a coordinating conjunction like 'and', you must place a comma before the conjunction.","incorrect":[{"choice":"We went to the zoo and we, fed the animals.","category":"misplaced comma","reason":"Placing the comma after 'we' creates an unnatural break in the sentence. Commas should separate independent clauses, not split a subject from its verb."},"",{"choice":"We went to the zoo and we fed the animals.","category":"missing comma","reason":"This sentence connects two complete ideas, so it requires a comma before the word 'and' to signal where the first thought ends and the second begins."},{"choice":"We went to the zoo and we fed, the animals.","category":"misplaced comma","reason":"A comma between 'fed' and 'the animals' separates a verb from its object. This disrupts the flow of the sentence and is not grammatically necessary."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":19,"sourceFile":"Basic-2_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"When joining two complete sentences with a conjunction like 'and', 'but', or 'or', use a comma before the conjunction to separate the two independent thoughts.","example":"I like pizza, and I like pasta. (Correct) / I like pizza and I like pasta. (Incorrect - needs comma) / I like pizza, and pasta. (Incorrect - not two complete sentences)","strategyClue":"Identify the two separate subjects and verbs in the sentence. If there are two complete ideas being joined together, look for the spot right before the joining word to insert your comma.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0020","version":3,"contentHash":"sha256:9d89b5f3aed3a9df1d3e3bd7be89fceb5bc705a3a401d1fd6c56e70f77a591b7","question":"Which sentence has the correct use of the comma?","choices":["If you practice often, skating is easy.","If you, practice often skating is easy.","If you practice often skating, is easy.","If you practice, often skating is easy."],"correct":0,"explanation":{"correct":"Answer: If you practice often, skating is easy. This is a complex sentence that starts with a dependent clause. When a sentence starts with an 'If' clause, you must place a comma after the clause to separate it from the main part of the sentence.","incorrect":["",{"choice":"If you, practice often skating is easy.","category":"misplaced comma","reason":"Placing a comma after 'you' breaks the flow of the dependent clause 'If you practice'. Commas should be used to separate whole clauses, not to chop up a single phrase."},{"choice":"If you practice often skating, is easy.","category":"misplaced comma","reason":"Placing a comma before 'is' breaks the subject 'skating' away from its verb 'is'. You should never put a comma between the subject and the verb of a sentence."},{"choice":"If you practice, often skating is easy.","category":"misplaced comma","reason":"This comma is placed too early. The dependent clause ends after the word 'often', so the comma must go there to mark the transition to the main idea."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":20,"sourceFile":"Basic-3_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"When a sentence begins with an introductory clause (often starting with words like 'if,' 'when,' or 'because'), use a comma to show where the introduction ends.","example":"If it rains, we will stay inside. When the bell rings, the class ends.","strategyClue":"Read the sentence out loud and look for the 'pause' where the opening condition ends and the main action begins; that is where your comma belongs.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0021","version":3,"contentHash":"sha256:b252739767ae11dd43d1bff2d62b3b373c62ccf7f0c3809faba2ef517a29c94a","question":"Choose the correct usage of a comma for an introductory word.","choices":["N o, you can’t eat a cookie.","No you can’t, eat a cookie.","No you can’t eat a cookie.","No you, can’t eat a cookie."],"correct":0,"explanation":{"correct":"Answer: No, you can’t eat a cookie. When using an introductory word like 'no' or 'yes' to start a sentence, place a comma immediately after that word to separate it from the rest of the sentence.","incorrect":["",{"choice":"No you can’t, eat a cookie.","category":"misplaced comma usage","reason":"This comma is in the wrong place. The comma must come right after the introductory word 'No' to signal a pause before the main clause starts."},{"choice":"No you can’t eat a cookie.","category":"missing introductory comma","reason":"This sentence is missing the comma after 'No'. Without it, the reader does not have a clear break between the introductory word and the statement that follows."},{"choice":"No you, can’t eat a cookie.","category":"comma separating verb","reason":"You should never put a comma between the subject ('you') and its verb ('can't'). The comma belongs only after the introductory word at the start of the sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":21,"sourceFile":"Basic-4_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Introductory words or interjections like 'Yes,' 'No,' or 'Well,' should always be followed by a comma to separate them from the main part of the sentence.","example":"Yes, I will go. / No, that is not true. / Well, let's start now.","strategyClue":"Read the sentence out loud and listen for the natural pause right after the first word. If you find yourself pausing after that first word, a comma should be placed there.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0022","version":3,"contentHash":"sha256:4efd36b3174c99ef854f28919284460f8b074a4a714d4c91a7dfa25fb48db889","question":"Which word should have a comma following it? Carrying a huge box the janitor knocked me into a drinking fountain.","choices":["huge","me","janitor","box"],"correct":3,"explanation":{"correct":"Answer: box. The phrase 'Carrying a huge box' is an introductory participial phrase that modifies the subject 'the janitor,' so it must be set off from the rest of the sentence with a comma.","incorrect":[{"choice":"huge","category":"incorrect comma placement","reason":"Placing a comma after 'huge' would split the adjective from the noun it describes ('box'), which disrupts the flow of the sentence."},{"choice":"me","category":"unnecessary punctuation","reason":"There is no grammatical rule requiring a comma after the direct object 'me' in this sentence; adding one would incorrectly break the link between the verb and the prepositional phrase."},{"choice":"janitor","category":"subject-verb separation","reason":"The word 'janitor' is the subject of the sentence. Putting a comma between the subject and its action ('knocked') makes the sentence very hard to read."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":22,"sourceFile":"Proficient-1_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Introductory phrases at the beginning of a sentence provide background information and must be followed by a comma to signal a pause before the main subject arrives.","example":"Walking to the store, I saw a cat. After the movie ended, we went home.","strategyClue":"Read the sentence out loud and listen for a natural pause after the opening descriptive phrase. Check if the words before the pause describe the subject that comes right after the pause.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0023","version":3,"contentHash":"sha256:dbf1d487bf835ec1b0af8137763197c641ba3a51cf3b6a670c38527239fb7aa0","question":"Which sentence is punctuated correctly?","choices":["Billy, on the other hand turned his report in yesterday.","Billy, on the other hand, turned his report in yesterday.","Billy on the other hand turned his report in yesterday.","Billy on the other hand, turned his report in yesterday."],"correct":1,"explanation":{"correct":"Answer: Billy, on the other hand, turned his report in yesterday. Interrupter phrases like 'on the other hand' must be set off by commas on both sides when they break the flow of a sentence.","incorrect":[{"choice":"Billy, on the other hand turned his report in yesterday.","category":"missing comma","reason":"This choice misses the second comma after 'hand'. Because the phrase 'on the other hand' acts as an interrupter, it needs a closing comma before the verb 'turned'."},"",{"choice":"Billy on the other hand turned his report in yesterday.","category":"missing commas","reason":"This choice is missing both commas. Without them, it is hard to tell that the phrase 'on the other hand' is an added detail rather than part of the main action."},{"choice":"Billy on the other hand, turned his report in yesterday.","category":"missing initial comma","reason":"This choice is missing the opening comma before 'on'. You must use a pair of commas to 'hug' the phrase 'on the other hand' to show it is an interruption."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":23,"sourceFile":"Proficient-4_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Parenthetical expressions or interrupters are extra phrases that break the flow of a sentence; they should be separated from the main sentence with commas.","example":"I, however, prefer blue. The rain, unfortunately, spoiled our picnic.","strategyClue":"Try reading the sentence aloud and pausing where the phrase begins and ends. If your voice naturally pauses at both spots, you likely need a comma at each of those positions.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0024","version":3,"contentHash":"sha256:3c2be3f42e1a48505417b366944f3c471a643f636dafe9a139cf4cc1078b231e","question":"Which sentence uses commas correctly?","choices":["The students, gave the principal Mr. Smith a special award.","The students gave, Mr. Smith a special award.","The students gave the principal, Mr. Smith, a special award.","The students gave the principal Mr. Smith, a special award."],"correct":2,"explanation":{"correct":"Answer: The students gave the principal, Mr. Smith, a special award. This sentence correctly uses commas to set off an appositive—a word or phrase that renames the noun 'principal'—because 'Mr. Smith' adds extra information that is not strictly necessary to identify the person.","incorrect":[{"choice":"The students, gave the principal Mr. Smith a special award.","category":"unnecessary comma usage","reason":"You should never put a comma between the subject ('The students') and the verb ('gave'). This comma creates an unnatural break in the sentence flow."},{"choice":"The students gave, Mr. Smith a special award.","category":"incorrect comma placement","reason":"Placing a comma after the verb 'gave' separates it from the object, which confuses the reader. A comma should only appear here if it is part of a list or an appositive phrase."},"",{"choice":"The students gave the principal Mr. Smith, a special award.","category":"incomplete appositive commas","reason":"When you use commas to set off an appositive like 'Mr. Smith,' you must place a comma before AND after the name. A single comma is not enough to frame the information correctly."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","editing"],"feedbackFocus":"use the mechanics clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":24,"sourceFile":"Proficient-5_Mechanics and Punctuation.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use commas to set off an appositive (a name or phrase that renames a noun) by placing one before and one after the extra information.","example":"My dog, Buster, loves to play. My brother, a talented chef, cooked dinner.","strategyClue":"Try reading the sentence while skipping the name or phrase between the commas. If the sentence still makes sense without those words, you need a comma on both sides of that phrase.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0025","version":3,"contentHash":"sha256:0b520884b01f954de5ffc908265bdac4a170b8985b3aadb8e71ec767cfce6320","question":"Which sentence is punctuated correctly?","choices":["Before leaving for school while our hot chocolate cools my sister and I watch TV.","Before leaving for school while our hot chocolate cools, my sister and I watch TV.","Before leaving for school, while our hot chocolate cools, my sister and I watch TV.","Before leaving for school, while our hot chocolate cools, my sister and I, watch TV."],"correct":2,"explanation":{"correct":"Answer: Before leaving for school, while our hot chocolate cools, my sister and I watch TV. This sentence correctly uses commas to set off two introductory dependent clauses that precede the main clause.","incorrect":[{"choice":"Before leaving for school while our hot chocolate cools my sister and I watch TV.","category":"missing commas","reason":"This sentence lacks necessary commas to separate the introductory phrases from the main part of the sentence, making it difficult to read and grammatically incomplete."},{"choice":"Before leaving for school while our hot chocolate cools, my sister and I watch TV.","category":"incomplete punctuation","reason":"While it includes one comma, the sentence still requires a comma after the first introductory phrase to properly set off both distinct clauses before the main action."},"",{"choice":"Before leaving for school, while our hot chocolate cools, my sister and I, watch TV.","category":"unnecessary comma","reason":"The comma placed after 'I' incorrectly separates the subject from its verb, breaking the flow of the sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":25,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":14,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Introductory clauses and phrases that come before the main subject of a sentence should be set off by commas. A comma tells the reader to pause.","example":"If it rains, we will stay inside. After the movie ended, we went home.","strategyClue":"Read the sentence out loud and look for natural pauses where the introductory thoughts end and the main action begins; identify where you hear these pauses to place your commas.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0026","version":3,"contentHash":"sha256:cccda336188ebce6492630737130949477b58c4e83c67976474cd8eaf86ee67f","question":"Where do commas belong in the sentence below? Exhausted __ tired __ of jogging __ around the track __ Elmer sat __ holding his A B C D E head __in his hands __ muttering to himself. F G This sentence is:","choices":["B, C, G","A, D, G","C, E, F","A, C, E"],"correct":1,"explanation":{"correct":"Answer: A, D, G. Commas are needed after the introductory adjectives 'Exhausted' and 'tired', after the introductory phrase 'around the track', and to set off the parenthetical phrase 'muttering to himself'.","incorrect":[{"choice":"B, C, G","category":"incorrect comma placement","reason":"Placing commas here breaks apart the phrase 'tired of jogging' and creates unnecessary pauses that disconnect the verb from its modifier."},"",{"choice":"C, E, F","category":"incorrect comma placement","reason":"These placements interrupt the natural flow of the sentence by separating the preposition 'of' from 'jogging' and 'holding' from 'his head'."},{"choice":"A, C, E","category":"incorrect comma placement","reason":"While 'A' is correct, the other positions separate essential parts of phrases, such as 'jogging around the track' and 'holding his head', which should stay together."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":26,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":15,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Commas are used to separate introductory words, phrases, or clauses from the rest of the main sentence to help the reader understand where one thought ends and the next begins.","example":"Hungry and tired, the puppy slept. After a long walk, we went home. He sat down, looking very sad.","strategyClue":"Read the sentence out loud and notice where you naturally pause for breath or where a descriptive thought begins. Look for introductory adjectives, phrases that tell 'where' or 'when', and extra details added at the end.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0027","version":3,"contentHash":"sha256:8d78de3a685c440cc2c24fcf332770b0f895ab5c204b25c996304a95de8aa915","question":"Which sentence is punctuated correctly?","choices":["Mary Richards, hoping to make the team practiced every day.","Mary Richards, hoping to make the team, practiced every day.","Mary Richardshoping to make the team practiced every day.","Mary Richardshoping to make the team, practiced every day."],"correct":1,"explanation":{"correct":"Answer: Mary Richards, hoping to make the team, practiced every day. When you add extra information in the middle of a sentence that is not essential to the main meaning, you must surround it with commas on both sides.","incorrect":[{"choice":"Mary Richards, hoping to make the team practiced every day.","category":"missing closing comma","reason":"You opened the extra information with a comma after 'Richards', but you need a second comma after 'team' to show where the extra detail ends."},"",{"choice":"Mary Richardshoping to make the team practiced every day.","category":"missing word spacing","reason":"The words 'Richards' and 'hoping' have been accidentally squashed together; always ensure there is a clear space between separate words."},{"choice":"Mary Richardshoping to make the team, practiced every day.","category":"missing word spacing","reason":"Like the previous option, 'Richards' and 'hoping' are merged into one word, which makes the sentence difficult to read."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":27,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":26,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use commas to set off an interrupter or a phrase that adds extra information to a sentence. If you can remove the phrase and the sentence still makes sense, it likely needs commas around it.","example":"My dog, a golden retriever, loves to run. The park, located near the school, is closed today.","strategyClue":"Read the sentence and find the part that adds extra, non-essential detail. Try reading the sentence aloud while skipping that part; if it still sounds complete, place a comma at both the beginning and the end of that specific phrase.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0028","version":3,"contentHash":"sha256:380025a23b5a2e6004437b904ac20bc6495afc283227b986cf8aefe69fff32c8","question":"Read the sentence. After you take the boxes to the dumpster, come back in side, and help me This sentence is a/an","choices":["command.","question.","statement.","exclamation."],"correct":0,"explanation":{"correct":"Answer: command. A command, or imperative sentence, gives an order or a request. The sentence begins with the verb 'come' and 'help', showing it is telling someone what to do.","incorrect":["",{"choice":"question.","category":"sentence type error","reason":"A question asks for information and usually ends with a question mark. This sentence does not ask anything; it directs someone to perform an action."},{"choice":"statement.","category":"sentence type error","reason":"A statement provides facts or opinions and usually ends with a period. While this ends with a period, its primary purpose is to give an instruction, not just report information."},{"choice":"exclamation.","category":"sentence type error","reason":"An exclamation shows strong feeling and usually ends with an exclamation point. This sentence is calm and instructional, not filled with excitement or surprise."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":28,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":15,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"An imperative sentence (command) gives a direction or request and often starts with a verb. It can end with a period or an exclamation point.","example":"Clean your room. Please pass the salt! Close the door.","strategyClue":"Look at the first word of the sentence. If it is an action word (verb) and the sentence is telling someone to do something, it is likely a command.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0029","version":3,"contentHash":"sha256:ea79afd13415399837e8c2a79135deba33d94a103d7a1b9e889b68ead23f5e92","question":"Which sentence is a command?","choices":["Are you going to finish your homework?","At the beginning of class.","I will call you later.","Answer the phone."],"correct":3,"explanation":{"correct":"Answer: Answer the phone. A command, or imperative sentence, gives an instruction or a request and often has an 'invisible' subject 'you' that is understood by the reader.","incorrect":[{"choice":"Are you going to finish your homework?","category":"interrogative sentence","reason":"This sentence ends with a question mark and asks for information, which makes it an interrogative sentence, not a command."},{"choice":"At the beginning of class.","category":"sentence fragment","reason":"This is a fragment because it lacks a main verb and does not express a complete thought. Commands must be complete sentences."},{"choice":"I will call you later.","category":"declarative sentence","reason":"This sentence makes a statement about the future, which is a declarative sentence. A command must tell someone to perform an action."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":29,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":1,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"An imperative sentence (a command) gives a direct order, instruction, or request, and it typically ends with a period or an exclamation point.","example":"Close the door. (Command) vs. Are you closing the door? (Question)","strategyClue":"Ask yourself: 'Does this sentence tell someone to do something?' If the sentence is asking for information or making a simple statement, it is not a command.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0030","version":3,"contentHash":"sha256:ff052db68fd3ecb4ceee0524e7215beba0891854008f177210ead6976669cba8","question":"Which comma is in the correct place?","choices":["May 9, 2020","May 9 2020","May 9 2, 020","May 9 202,0"],"correct":0,"explanation":{"correct":"Answer: May 9, 2020. When writing a full date, you must place a comma between the day and the year to separate the two numbers.","incorrect":["",{"choice":"May 9 2020","category":"missing comma","reason":"This date is missing the required comma between the day and the year. Without the comma, the two numbers run together, making the date harder to read."},{"choice":"May 9 2, 020","category":"incorrect comma placement","reason":"The comma is placed in the middle of the year 2020. Commas are used to separate date parts, not to split the digits of a year."},{"choice":"May 9 202,0","category":"incorrect comma placement","reason":"This comma is placed incorrectly at the end of the year. Commas in dates should only appear between the day and the year."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":30,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":17,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"When writing out a full date including the month, day, and year, always put a comma after the day to separate it from the year.","example":"October 31, 2023; July 4, 1776; January 1, 2000","strategyClue":"Look at the numbers at the end of the date. Identify where the day ends and the year begins, then insert the separator at that exact spot.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0031","version":3,"contentHash":"sha256:b453bba059ab2dd0ce5185708efd031377d1a46cd61cbea208de777e73653afc","question":"In which sentence are the commas used correctly?","choices":["We went to the store and bought bread, eggs, and milk.","We, went to the store and bought bread eggs and milk.","We went to, the store and, bought bread eggs and milk.","We went, to the store and bought bread eggs, and milk."],"correct":0,"explanation":{"correct":"Answer: We went to the store and bought bread, eggs, and milk. Commas are used to separate items in a list of three or more things. Placing a comma after each item except the last one makes the sentence clear.","incorrect":["",{"choice":"We, went to the store and bought bread eggs and milk.","category":"misplaced comma","reason":"You should not place a comma between the subject and the verb. 'We' is the subject and 'went' is the verb, so they should not be separated."},{"choice":"We went to, the store and, bought bread eggs and milk.","category":"unnecessary punctuation","reason":"Commas are used to separate items in a list, not to break up phrases like 'went to the store'. Also, this choice lacks the necessary commas between the list items."},{"choice":"We went, to the store and bought bread eggs, and milk.","category":"incorrect comma placement","reason":"The comma after 'went' is unnecessary, and the list items 'bread' and 'eggs' are not properly separated by a comma."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":31,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":20,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use commas to separate three or more items in a list. A comma is placed after every item in the series except for the final item.","example":"Correct: I like red, blue, and green. Incorrect: I like red blue and green.","strategyClue":"Look for a series of three or more things being listed in the sentence. Check to see if there is a comma separating each distinct item so that they do not run together.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0032","version":3,"contentHash":"sha256:27524fe505457470abfcbb91ad3cf2659818b701dd721b5caebed788d069584f","question":"Which sentence has the comma in the correct place?","choices":["My friend lives, in Seattle Washington.","My friend lives in Seattle Washington.","My friend lives in Seattle, Washington.","My friend lives in, Seattle Washington."],"correct":2,"explanation":{"correct":"Answer: My friend lives in Seattle, Washington. When you write a city followed by its state, you must place a comma between the city and the state to separate them correctly.","incorrect":[{"choice":"My friend lives, in Seattle Washington.","category":"incorrect comma placement","reason":"You should not place a comma between the verb 'lives' and the preposition 'in'. A comma here interrupts the natural flow of the sentence."},{"choice":"My friend lives in Seattle Washington.","category":"missing comma","reason":"This sentence is missing the required comma between the city name 'Seattle' and the state name 'Washington'."},"",{"choice":"My friend lives in, Seattle Washington.","category":"punctuation and spelling error","reason":"This sentence contains an unnecessary comma after 'in' and a spelling error in 'friend', both of which make the sentence incorrect."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":32,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":44,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"When writing a city and state together, use a comma after the city name to separate it from the state.","example":"Chicago, Illinois; Austin, Texas; Denver, Colorado.","strategyClue":"Look for the spot where the name of the place changes from a city to a state. Insert the comma exactly between those two specific proper nouns.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0033","version":4,"contentHash":"sha256:1938442e3f85b3de01837279f08dfe680b9ddd65fe5a7c35fb28656b4b4fc4ec","question":"Which comma is used correctly in the closing of the letter?","choices":["Dear Mary, / I am doing well. / Your friend","Dear Mary, / I am doing well. / ,Your friend","Dear Mary, / I am doing well. / Your friend,","Dear Mary, / I am doing well. / Your, friend"],"correct":2,"explanation":{"correct":"Answer: Dear Mary, / I am doing well. / Your friend,. In a letter, the closing (such as 'Your friend' or 'Sincerely') must be followed by a comma to correctly introduce the sender's name.","incorrect":[{"choice":"Dear Mary, / I am doing well. / Your friend","category":"missing closing punctuation","reason":"When you finish a letter, the closing phrase needs a comma after it to separate it from your name. Without the comma, the punctuation is incomplete."},{"choice":"Dear Mary, / I am doing well. / ,Your friend","category":"incorrect punctuation placement","reason":"Commas in a letter closing should come after the phrase, not before it. Placing the comma at the start of the closing is grammatically incorrect."},"",{"choice":"Dear Mary, / I am doing well. / Your, friend","category":"incorrect comma usage","reason":"The comma should only appear after the entire closing phrase, not between the words of the closing itself. Putting a comma between 'Your' and 'friend' breaks up the phrase incorrectly."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":33,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":50,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"The closing of a letter is a short phrase that ends with a comma to bridge the gap between your message and your name.","example":"Sincerely, / Your pal, / With love,","strategyClue":"Look at the closing phrase as a single unit. Identify which punctuation mark is used to separate that unit from the signature line below it.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0034","version":3,"contentHash":"sha256:1249d84a13b7bdf270df433fb4c12e78fa07a18a9b58d5a780ecd94942a0e741","question":"What parts would you use for a story?","choices":["comma","beginning, middle, end","ABC order","map skills"],"correct":1,"explanation":{"correct":"Answer: beginning, middle, end. A complete story needs these three structural parts to make sense and flow in a logical order.","incorrect":[{"choice":"comma","category":"punctuation mark","reason":"A comma is a punctuation mark used to separate items in a list or pauses in a sentence, not a structural part of a story."},"",{"choice":"ABC order","category":"organizational tool","reason":"ABC order is a way to arrange words or items alphabetically, not a sequence used to build a narrative plot."},{"choice":"map skills","category":"geographic concept","reason":"Map skills are used to read and understand geography and locations, which are not the same thing as the elements of a written story."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":34,"sourceFile":"Basic-2_Writing strategies_Application_Style.pdf","sourceQuestionNumber":3,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Every story follows a standard structure consisting of a beginning to set the scene, a middle where the events happen, and an end to wrap up the action.","example":"Beginning: Once there was a puppy. Middle: He got lost in the park. End: He found his way home.","strategyClue":"Think about how a movie or a book is organized from the moment it starts until it finishes.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0035","version":3,"contentHash":"sha256:83ec4a00e1f28f47393fb9147fa8b62579e1a11c74981cdfea3eaf3c902f6b5a","question":"Read the sentence. Are you coming home for dinner This sentence is a(n)","choices":["command","question","statement","exclamation"],"correct":1,"explanation":{"correct":"Answer: question. This sentence is a question because it asks for information and ends with a question mark. It begins with the helping verb 'Are', which is a classic signal that an inquiry is being made.","incorrect":[{"choice":"command","category":"imperative sentence error","reason":"A command gives an order, such as 'Come home for dinner.' This sentence asks if you are coming, rather than telling you to do it."},"",{"choice":"statement","category":"declarative sentence error","reason":"A statement provides information or facts, like 'You are coming home for dinner.' Your sentence asks for information, so it is not a statement."},{"choice":"exclamation","category":"exclamatory sentence error","reason":"An exclamation shows strong emotion or excitement and usually ends with an exclamation point. This sentence is simply asking for information."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":35,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":15,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A question (or interrogative sentence) asks for information and always ends with a question mark.","example":"Question: Where is my hat? Command: Put on your hat. Statement: That is your hat.","strategyClue":"Look at the end punctuation of the sentence and ask yourself: Does this sentence express excitement, give an order, tell a fact, or seek information from someone else?","link":"","linkText":""}},{"id":"punctuation-commas-series-q0036","version":3,"contentHash":"sha256:b30ec92c7febaad041a93e2a7e9b982ec2b876019abda6a90bc4e3a52bb5bf06","question":"Kevin has grown several inches according to his chart. This sentence:","choices":["is an exclamation","makes a statement","asks a question","give s a command"],"correct":1,"explanation":{"correct":"Answer: makes a statement. This sentence is a declarative sentence because it provides information about Kevin's height without showing strong emotion, asking for information, or giving an order.","incorrect":[{"choice":"is an exclamation","category":"incorrect sentence type","reason":"An exclamation would end with an exclamation point (!) and express strong feeling or surprise. This sentence ends with a period and simply tells a fact."},"",{"choice":"asks a question","category":"incorrect sentence type","reason":"A question would end with a question mark (?) and seek information. This sentence provides information rather than requesting it."},{"choice":"give s a command","category":"incorrect sentence type","reason":"A command (imperative sentence) tells someone what to do. Since this sentence describes something happening to Kevin, it is not telling anyone to perform an action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":36,"sourceFile":"Basic-4_Writing strategies_Application_Style.pdf","sourceQuestionNumber":9,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A declarative sentence makes a statement or expresses an opinion and always ends with a period.","example":"The dog is sleeping. (Statement) / Put the dish away. (Command) / Is it raining? (Question) / Wow, that is huge! (Exclamation)","strategyClue":"Look at the punctuation at the end of the sentence and ask yourself: 'Am I being told a fact, asked something, given an order, or hearing an expression of excitement?'","link":"","linkText":""}},{"id":"punctuation-commas-series-q0037","version":3,"contentHash":"sha256:56c3a9e1bef4e480cd76b03d02cd72bf024b55b8aa7b98226528a6da1c049301","question":"The thunder boomed The above sentence is:","choices":["a statement","a command","a question","an exclamation"],"correct":0,"explanation":{"correct":"Answer: a statement. A statement, or declarative sentence, simply tells us information and ends with a period. 'The thunder boomed' shares a fact about an event.","incorrect":["",{"choice":"a command","category":"imperative sentence","reason":"A command gives an instruction to someone, like 'Close the door.' Since 'The thunder boomed' is just providing information, it is not a command."},{"choice":"a question","category":"interrogative sentence","reason":"A question asks for information and ends with a question mark. Because this sentence ends with a period and doesn't ask anything, it is not a question."},{"choice":"an exclamation","category":"exclamatory sentence","reason":"An exclamation shows strong feeling or surprise and ends with an exclamation point. This sentence is a calm observation, not a burst of strong emotion."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":37,"sourceFile":"Basic-6_Writing strategies_Application_Style.pdf","sourceQuestionNumber":2,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A statement (declarative sentence) tells the reader information or shares a fact. It ends with a period.","example":"Statement: The dog barked. Command: Feed the dog. Question: Did the dog bark? Exclamation: The dog is huge!","strategyClue":"Look at the punctuation mark at the end of the sentence and ask yourself: 'Does this ask, order, or just inform?'","link":"","linkText":""}},{"id":"punctuation-commas-series-q0038","version":3,"contentHash":"sha256:49b001708f8e2257658c85689bddd29cedb994b4e280643b41a597d53ffc03f5","question":"Well do you want me to go to the store? In the sentence above, a comma should go between:","choices":["do, you","me, to","Well, do","go, to Sarah, Plain And Tall"],"correct":2,"explanation":{"correct":"Answer: Well, do. Introductory words like 'well' at the start of a sentence should be separated from the rest of the sentence with a comma.","incorrect":[{"choice":"do, you","category":"incorrect comma placement","reason":"Placing a comma between 'do' and 'you' interrupts the main verb and its subject. These words belong together, so they shouldn't be split."},{"choice":"me, to","category":"incorrect comma placement","reason":"There is no pause between 'me' and 'to' that requires a comma. A comma here would disrupt the flow of the sentence."},"",{"choice":"go, to Sarah, Plain And Tall","category":"incorrect comma placement","reason":"This is a book title and a phrase that shouldn't be broken up by commas. Placing commas inside this phrase makes the sentence very hard to read."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":38,"sourceFile":"Basic-6_Writing strategies_Application_Style.pdf","sourceQuestionNumber":9,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Introductory words like 'well,' 'yes,' or 'no' at the beginning of a sentence are often followed by a comma to show a slight pause.","example":"Well, we should go. Yes, I want to come. No, I cannot go.","strategyClue":"Read the sentence out loud and listen for where you naturally take a small breath or pause after the first word; that is where the comma belongs.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0039","version":3,"contentHash":"sha256:e501fc8f468298958d30fdef61367702faa64998eaa4afaadc8eadb20c9edddc","question":"Which sentence is punctuated correctly?","choices":["Sin ce, I’m starting in the game today, I’m really nervous.","Since I’m starting in the game today, I’m really nervous.","Since I’m starting, in the game today I’m really nervous.","Since I’m starting in the game today; I’m really nervous."],"correct":1,"explanation":{"correct":"Answer: Since I’m starting in the game today, I’m really nervous. A dependent clause starting with 'Since' must be separated from the main clause by a single comma at the end of the clause.","incorrect":[{"choice":"Sin ce, I’m starting in the game today, I’m really nervous.","category":"incorrect comma usage","reason":"You should not place a comma immediately after the introductory word 'Since' because it interrupts the flow of the phrase."},"",{"choice":"Since I’m starting, in the game today I’m really nervous.","category":"misplaced comma","reason":"The comma should mark the end of the entire dependent clause ('Since I’m starting in the game today'), not just the first part of it."},{"choice":"Since I’m starting in the game today; I’m really nervous.","category":"incorrect punctuation mark","reason":"A semicolon is used to connect two complete, independent sentences. Here, the first part is a dependent clause, so a comma is required."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":39,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":26,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"When a sentence begins with a dependent word like 'since,' 'because,' or 'if,' use a comma to separate the introductory clause from the rest of the sentence.","example":"Because it rained, we stayed inside. If you study, you will succeed. Since it is late, I am going to bed.","strategyClue":"Read the sentence out loud and pause where you naturally take a breath to separate the opening condition from the main thought; that is exactly where the comma belongs.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0040","version":4,"contentHash":"sha256:eb590a1769108c5c4e4e5651ba57dc66498e82658e2089864fc51737f8ae5e39","question":"Choose the punctuation that should go in the blank. − James ___ clean up your room now!","choices":["!",".",",",":"],"correct":2,"explanation":{"correct":"Answer: ,. When you are speaking directly to someone to give a command, use a comma before their name to set it off as a direct address.","incorrect":[{"choice":"!","category":"incorrect sentence punctuation","reason":"An exclamation point indicates strong emotion at the end of a sentence; placing it after the name separates the name from the instruction incorrectly."},{"choice":".","category":"incorrect sentence punctuation","reason":"A period marks the end of a sentence, not the separation between a command and the person being addressed."},"",{"choice":":","category":"incorrect punctuation mark","reason":"A colon is typically used to introduce a list or an explanation, not to address someone directly at the start of a command."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":40,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":32,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use a comma to separate the name of the person being addressed from the rest of the sentence.","example":"Sarah, please sit down. / Come here, Mom. / Wait for me, John.","strategyClue":"Identify the name of the person being spoken to, then look for the slight pause between that name and the action being requested.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0041","version":3,"contentHash":"sha256:e386b81ad039780e18bbbc790227c2256a79e3b696665b4d0fe99ed7c5ef0281","question":"Read the sentences. Waiting impatiently (a) the students shoved (b) and jostled each other (c) at the bus stop. Weighed down by his heavy backpack (d) Pete was squeezed to the endof the line. The bright yellow bus (e) arrived in a blue of flashing lights and familiar faces. Knowing it was inevitable (f) the students boarded the bus to school. Where should commas be placed in the passage above?","choices":["b, c, d","a, c, d","b, c, f","a, d, f"],"correct":3,"explanation":{"correct":"Answer: a, d, f. These commas are needed because they follow introductory phrases that describe the subject (e.g., 'Waiting impatiently,' 'Weighed down by his heavy backpack,' and 'Knowing it was inevitable').","incorrect":[{"choice":"b, c, d","category":"incorrect comma placement","reason":"Placing commas between the verbs 'shoved' and 'jostled' disrupts the flow of the sentence; only the introductory phrases need punctuation."},{"choice":"a, c, d","category":"incorrect comma placement","reason":"The phrase 'each other' is part of the action, not an introductory phrase, so it should not be followed by a comma."},{"choice":"b, c, f","category":"incorrect comma placement","reason":"This choice misses the necessary commas at positions 'a' and 'd' where the introductory descriptive phrases end."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":41,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":35,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Use a comma after an introductory phrase or dependent clause that comes before the main part of the sentence to show where the introduction ends.","example":"After the movie, we went home. Exhausted from the game, the player sat down. Because it was raining, I took my umbrella.","strategyClue":"Read the sentence and pause where you feel a natural break. If the words before the break describe the main subject or the situation, place a comma at that transition point.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0042","version":3,"contentHash":"sha256:c6a91daba990ddb3e5ca32a12340b9ac950d7a0ae1335350c83e587fdd93dd8e","question":"Read the sentence below. My friend who is a N.Y. Yankees fan has tickets to the season ’s opening game. After which wordor words should you place a comma?","choices":["f an","tickets","who, fan","friend, fan"],"correct":3,"explanation":{"correct":"Answer: friend, fan. The phrase 'who is a N.Y. Yankees fan' is a non-restrictive clause, which adds extra information about the friend. You must place a comma before the clause begins and after it ends to set it apart from the rest of the sentence.","incorrect":[{"choice":"f an","category":"fragmented word","reason":"Placing a comma in the middle of the word 'fan' breaks the word apart and creates a spelling error rather than a punctuation rule."},{"choice":"tickets","category":"incorrect comma placement","reason":"Placing a comma after 'tickets' creates an unnecessary pause that breaks the flow between the object of the sentence and the prepositional phrase that follows it."},{"choice":"who, fan","category":"misplaced comma","reason":"This places a comma after the relative pronoun instead of before the clause, which confuses the reader about where the additional information starts."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":42,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":42,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Non-restrictive clauses add extra, non-essential information to a sentence and must be set off by commas on both sides.","example":"My teacher, who is very kind, gave us extra time. The dog, which was barking, scared the cat.","strategyClue":"Try reading the sentence while skipping the part between the commas. If the sentence still makes sense and keeps its main meaning, you have found an extra detail that needs commas to separate it from the main sentence.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0043","version":3,"contentHash":"sha256:30d7ed2b805f487e550cc3615915f7e2c2cce63a67c0f3f10aed02e77a81946f","question":"Which sentence is punctuated correctly?","choices":["Jo se went to the game, and, Karla went to a movi e.","Jose went to the game and, Karla went to a movie.","Jose went to the game, and Karla went to a movie.","Jose went, to the game, and Karla, went to a movie."],"correct":2,"explanation":{"correct":"Answer: Jose went to the game, and Karla went to a movie. Use a comma before a coordinating conjunction (like 'and') when it connects two complete sentences (independent clauses).","incorrect":[{"choice":"Jo se went to the game, and, Karla went to a movi e.","category":"unnecessary punctuation","reason":"This choice adds an extra comma after 'and' and breaks the words 'Jose' and 'movie' with spaces, which is incorrect spelling and punctuation."},{"choice":"Jose went to the game and, Karla went to a movie.","category":"misplaced comma","reason":"You must place the comma before the word 'and' that connects the two sentences, not after it."},"",{"choice":"Jose went, to the game, and Karla, went to a movie.","category":"unnecessary comma usage","reason":"These commas interrupt the flow of the sentence by separating verbs from their objects unnecessarily. Commas should only be used to separate complete, independent clauses."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":43,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":47,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"When joining two complete sentences with a coordinating conjunction like 'and', 'but', or 'or', you must place a comma before that conjunction.","example":"I love soccer, and she loves tennis. / We wanted to go, but it started raining.","strategyClue":"Split the sentence at the conjunction. If you have two complete, independent thoughts on either side, check that you have included a comma exactly before the conjunction.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0044","version":3,"contentHash":"sha256:6736c5700137bc904babb8987f71f6de2b4dc6c506675b4499a06b78153e921e","question":"Read the sentence. I wish my hair had more curls and wasn’t so straight This sentence is a(n)","choices":["command.","question.","statement.","exclamation."],"correct":2,"explanation":{"correct":"Answer: statement. This sentence shares information or a wish, which is the function of a declarative sentence. It ends with a period and describes a thought or state of being.","incorrect":[{"choice":"command.","category":"imperative sentence type","reason":"A command gives an instruction or order. This sentence expresses a personal wish rather than telling someone what to do."},{"choice":"question.","category":"interrogative sentence type","reason":"A question asks for information and typically ends with a question mark. This sentence is providing information about the speaker's hair, not asking for an answer."},"",{"choice":"exclamation.","category":"exclamatory sentence type","reason":"An exclamation shows strong emotion or surprise and usually ends with an exclamation point. This sentence is a calm, neutral observation."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":44,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":15,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"A statement (declarative sentence) tells information and ends with a period. It is the most common type of sentence used to share facts, feelings, or ideas.","example":"Statement: My dog is hungry. / Command: Feed the dog. / Question: Is the dog hungry? / Exclamation: The dog is so hungry!","strategyClue":"Ask yourself: 'Is the speaker giving an order, asking for information, expressing strong excitement, or just sharing a simple thought?'","link":"","linkText":""}},{"id":"punctuation-commas-series-q0045","version":3,"contentHash":"sha256:82fbbab6f62060cb25b814299b806a7af47181696725031406c1343836e1bbb3","question":"Which comma is not in the correct place?","choices":["Newport, Rhode Island","April 25, 2009","apples, bananas, and pears","Yellowstone, National Park"],"correct":3,"explanation":{"correct":"Answer: Yellowstone, National Park. Commas are used to separate city and state, dates, or items in a list. Putting a comma between an adjective and a proper noun or between two parts of a single name breaks the flow and is grammatically incorrect.","incorrect":[{"choice":"Newport, Rhode Island","category":"city and state comma","reason":"This is correct because we always use a comma to separate a city from the state or country that follows it."},{"choice":"April 25, 2009","category":"date format comma","reason":"This is correct because when writing a date in the format Month Day, Year, a comma must follow the day to separate it from the year."},{"choice":"apples, bananas, and pears","category":"list punctuation","reason":"This is correct because commas are used to separate three or more items in a list so the reader knows where each item begins and ends."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":45,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":17,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"Commas are used to signal a brief pause or to separate items, dates, and locations. They should not be used to split a name or a single noun phrase apart.","example":"Correct: Paris, France; July 4, 1776; lions, tigers, and bears. Incorrect: Micky, Mouse; Boston, Massachusetts,","strategyClue":"Read the phrases aloud and listen for a natural pause. If you place a comma where you would pause to separate two distinct categories (like a city and its state), it is likely correct. If the comma sits inside a single name, it is almost certainly wrong.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0046","version":4,"contentHash":"sha256:1e6dfdfffe91150b9f618f575dc38d408d090c69c465c9eb7dd166523fc1ec38","question":"After which word should you place a comma? Because she volunteered to make cookies Beth had to go to the store to bu y ingredients.","choices":["cookies,","volunteered,","Because,","store, May 10, 2019"],"correct":0,"explanation":{"correct":"Answer: cookies,. When a sentence begins with a dependent clause starting with a subordinating conjunction like 'Because', you must place a comma after the clause ends to separate it from the main independent clause.","incorrect":["",{"choice":"volunteered,","category":"improper sentence punctuation","reason":"Placing a comma here splits the verb 'volunteered' from the object 'to make cookies', which breaks the flow of the phrase."},{"choice":"Because,","category":"subordinating conjunction error","reason":"You should never put a comma immediately after a subordinating conjunction like 'Because' at the beginning of a sentence; it disrupts the connection between 'Because' and the subject 'she'."},{"choice":"store, May 10, 2019","category":"unnecessary punctuation","reason":"This option introduces an incorrect date format and adds an unnecessary comma that interrupts the logical flow of the sentence action."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","mechanics","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sequence":46,"sourceFile":"Proficient-3_Writing strategies_Application_Style.pdf","sourceQuestionNumber":6,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"studyAid":{"definition":"When a sentence starts with a dependent clause, use a comma to separate it from the rest of the sentence. The comma acts as a 'pause' before the main part of the sentence begins.","example":"Because it was raining, we stayed inside. After the movie ended, we went home.","strategyClue":"Read the sentence out loud and find the point where the introductory phrase finishes and the main character begins their action. That transition point is where the comma belongs.","link":"","linkText":""}},{"id":"punctuation-commas-series-q0047","version":3,"contentHash":"sha256:3e81aa82f243e6ce730da2d625a091cc7c3f76120e9651203b1e237f03b9273c","question":"Where in the following sentence would you place a comma? Mom makes me breakfast before school but I don’t have enough time to eat it.","choices":["after the word “breakfast”","after the word “school”","after the word “have”","after the word “time”"],"correct":1,"explanation":{"correct":"Answer: after the word “school”. This sentence contains two independent clauses joined by the conjunction 'but'. You must place a comma before coordinating conjunctions when they link two complete thoughts.","incorrect":[{"choice":"after the word “breakfast”","category":"misplaced comma","reason":"Placing a comma here interrupts the natural flow of the first thought, 'Mom makes me breakfast before school'. Keep the parts of the sentence together unless you are connecting two complete ideas."},"",{"choice":"after the word “have”","category":"verb-object separation","reason":"A comma after 'have' would separate the verb from its object. Never put a comma between a verb and the word that follows it unless there is a specific reason to pause."},{"choice":"after the word “time”","category":"incorrect punctuation","reason":"This comma is placed at the end of the sentence. A comma should never be used as a replacement for a period or to end a complete thought."}]},"studyAid":{"definition":"Use a comma before a coordinating conjunction (like 'and', 'but', or 'or') when it connects two complete sentences together.","example":"I like cake, but he likes pie. We went to the park, and we saw ducks. She ran fast, but she missed the bus.","strategyClue":"Find the conjunction in the sentence. Check if there is a complete thought (a subject and a verb) on the left side AND the right side of that conjunction; if both sides can stand alone, put a comma right before the conjunction.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Advanced Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":47,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0048","version":3,"contentHash":"sha256:03300a282dbc954fa233b5bf2194f7be6a2d93b98edd44c15ccf6558299f600b","question":"How should the following sentence be punctuated? The weather was cold and wet outside yet we really needed the rain.","choices":["A comma belongs after the word “” outside","A comma belongs after the word “cold”","A comma belongs after the word “yet”","This sentence does not need a comma."],"correct":0,"explanation":{"correct":"Answer: A comma belongs after the word “outside”. When you join two complete sentences (independent clauses) with a coordinating conjunction like 'yet', you must place a comma before the conjunction.","incorrect":["",{"choice":"A comma belongs after the word “cold”","category":"misplaced comma","reason":"Placing a comma after 'cold' interrupts the compound adjective phrase 'cold and wet'. You do not need a comma between two adjectives joined by 'and' when they are part of the same description."},{"choice":"A comma belongs after the word “yet”","category":"misplaced punctuation","reason":"A comma should appear before the conjunction 'yet', not after it. Placing it after the conjunction creates an unnecessary break that disrupts the flow of the sentence."},{"choice":"This sentence does not need a comma.","category":"missing comma","reason":"This sentence consists of two independent clauses joined by 'yet'. A comma is required to properly connect these two distinct thoughts."}]},"studyAid":{"definition":"Use a comma before a coordinating conjunction (like and, but, or, yet) when it connects two complete sentences.","example":"I wanted to play, but it was raining. The sky turned gray, yet the sun came out.","strategyClue":"Cover the conjunction and read the words on both sides of it. If both sides are complete sentences that could stand alone, you need a comma before the conjunction.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Advanced Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":48,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0049","version":3,"contentHash":"sha256:4b535956041cf1684f215bfdd1dec9092eb407608b50bf289808970ab0b89c7f","question":"What is the purpose of an imperative sentence?","choices":["to ask a question","to give a command","to show emotion","to make a statement"],"correct":1,"explanation":{"correct":"Answer: to give a command. Imperative sentences are used to tell someone to do something, whether it is a firm order or a polite request.","incorrect":[{"choice":"to ask a question","category":"interrogative sentence function","reason":"Sentences that ask questions are called interrogative sentences. Imperative sentences give directions rather than seeking information."},"",{"choice":"to show emotion","category":"exclamatory sentence function","reason":"Sentences used to show strong emotion or excitement are called exclamatory sentences. They usually end with an exclamation point, but they do not necessarily give a command."},{"choice":"to make a statement","category":"declarative sentence function","reason":"Sentences that tell facts or share information are called declarative sentences. These are different from imperative sentences, which instruct someone to perform an action."}]},"studyAid":{"definition":"An imperative sentence is a type of sentence that gives a command, a request, or a piece of advice.","example":"Close the door. (Command) Please pass the salt. (Request) Brush your teeth twice a day. (Advice)","strategyClue":"Ask yourself if the sentence is trying to make you do something. If you can add a 'you' (the implied subject) to the beginning, it is likely an imperative sentence.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Advanced Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":49,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0050","version":3,"contentHash":"sha256:fbbcb4afd5d4dcbfc79621b7e490eea34cf41101c36fb800e61c6b9c27b054bb","question":"How should the following sentence be punctuated? She didn’t speak to anyone and nobody spoke to her.","choices":["A comma belongs after the word “anyone”","A comma belongs after the word “nobody”","A comma belongs after the word “spoke”","This sentence does not need a comma."],"correct":0,"explanation":{"correct":"Answer: A comma belongs after the word “anyone”. This is a compound sentence consisting of two independent clauses joined by the coordinating conjunction 'and', which requires a comma before it.","incorrect":["",{"choice":"A comma belongs after the word “nobody”","category":"incorrect comma placement","reason":"Placing a comma after 'nobody' breaks up the second clause incorrectly. Comma placement should happen between the two separate ideas, not inside them."},{"choice":"A comma belongs after the word “spoke”","category":"incorrect comma placement","reason":"Adding a comma after 'spoke' separates the verb from its object in the second clause, which confuses the reader and disrupts the flow of the sentence."},{"choice":"This sentence does not need a comma.","category":"missing conjunction comma","reason":"Because both 'She didn’t speak to anyone' and 'nobody spoke to her' are complete sentences, you must use a comma before the 'and' that joins them."}]},"studyAid":{"definition":"When joining two complete sentences with a coordinating conjunction like 'and', 'but', or 'or', you must place a comma before the conjunction.","example":"I walked to the store, and he stayed home. / She studied hard, but she still felt nervous.","strategyClue":"Check if there is a complete sentence on both sides of the conjunction 'and'. If you have a full subject and verb on each side, look for the comma to separate those two parts.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Advanced Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":8,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":50,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0076","version":3,"contentHash":"sha256:4c473a97b368dc451296fc8bf2d3b8af1829e001238a9f5bbace962b769b85e3","question":"Which uses a comma correctly before a coordinating conjunction?","choices":["I in vited Stacy but now, I wish I didn’t.","We bought a larger car so, we would have more room.","The basketball is in the garage, but it is flat.","You can have a sandwich, or, you can have pizza."],"correct":2,"explanation":{"correct":"Answer: The basketball is in the garage, but it is flat. A comma is required before a coordinating conjunction (FANBOYS) only when it joins two complete sentences (independent clauses).","incorrect":[{"choice":"I in vited Stacy but now, I wish I didn’t.","category":"missing comma","reason":"When joining two independent clauses with 'but', the comma must come before the conjunction, not after it."},{"choice":"We bought a larger car so, we would have more room.","category":"misplaced comma","reason":"You should not place a comma between the conjunction 'so' and the start of the second clause. The comma must precede the 'so'."},"",{"choice":"You can have a sandwich, or, you can have pizza.","category":"unnecessary punctuation","reason":"While a comma before 'or' is correct, adding a second comma immediately after it is unnecessary and breaks the flow of the sentence."}]},"studyAid":{"definition":"When joining two complete sentences with a coordinating conjunction (for, and, nor, but, or, yet, so), place a comma before the conjunction.","example":"I like cake, and I like pie. (Correct) / I like cake and pie. (No comma needed because 'pie' is not a full sentence).","strategyClue":"Check if both parts of the sentence on either side of the conjunction could stand alone as complete sentences. If both sides are full thoughts, place the comma immediately before the conjunction word.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Basic Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":6,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":76,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0078","version":3,"contentHash":"sha256:52c581dcdcdd86ec769c14b243c874023ccdccac8f299101f37c85a5710aa280","question":"What is the purpose of a declarative sentence?","choices":["to give a command","to ask a question","to show emotion","to make a statement"],"correct":3,"explanation":{"correct":"Answer: to make a statement. A declarative sentence is used specifically to relay information, facts, or ideas by making a simple statement.","incorrect":[{"choice":"to give a command","category":"imperative sentence type","reason":"This describes an imperative sentence. Commands tell someone to do something, whereas declarative sentences simply provide information."},{"choice":"to ask a question","category":"interrogative sentence type","reason":"Sentences that ask questions are called interrogative sentences. Declarative sentences end with a period, not a question mark."},{"choice":"to show emotion","category":"exclamatory sentence type","reason":"This describes an exclamatory sentence, which expresses strong feelings and usually ends with an exclamation point."},""]},"studyAid":{"definition":"A declarative sentence is a sentence that makes a statement, provides a fact, or shares an opinion and ends with a period.","example":"The dog is sleeping. (Declarative) vs. Is the dog sleeping? (Interrogative)","strategyClue":"Ask yourself: 'Does this sentence give me a piece of information, or is it trying to get something from me like a response or an action?'","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Basic Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":8,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":78,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0089","version":3,"contentHash":"sha256:44520781fd74d3139ce4624db52afa7df7fb7ace00ffa8bb8083dcd34a8a7c42","question":"What is the purpose of an imperative sentence?","choices":["to ask a question","to show emotion","to make a statement","to give a command"],"correct":3,"explanation":{"correct":"Answer: to give a command. Imperative sentences are designed to direct someone to do something, often using an implied subject 'you'.","incorrect":[{"choice":"to ask a question","category":"interrogative sentence type","reason":"Asking a question is the job of an interrogative sentence, which always ends with a question mark, not a command."},{"choice":"to show emotion","category":"exclamatory sentence type","reason":"Sentences that show strong emotion or surprise are called exclamatory sentences. An imperative sentence focuses on an action to be taken rather than an emotional reaction."},{"choice":"to make a statement","category":"declarative sentence type","reason":"Making a statement or sharing information is the purpose of a declarative sentence. An imperative sentence goes beyond a statement by telling someone to perform an action."},""]},"studyAid":{"definition":"An imperative sentence gives a command, a request, or an instruction.","example":"Close the door. (Command); Please pass the salt. (Request); Turn left at the corner. (Instruction)","strategyClue":"Ask yourself if the sentence is trying to make someone DO something. If the sentence is telling a person to act, it fits the imperative category.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Proficient Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":9,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":89,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0093","version":3,"contentHash":"sha256:218989120fb12782f767def02dc5854fdd037e8f72244ea1011bf6c536fba95d","question":"How should the following sentence be punctuated? A huge gust of wind hit our house and our patio furniture was thrown from the deck.","choices":["A comma belongs after the word “” hit","A comma belongs after the word “” house","A comma belongs after the word “and”","This sentence does not need a comma."],"correct":1,"explanation":{"correct":"Answer: A comma belongs after the word “house”. This sentence contains two complete thoughts joined by the coordinating conjunction 'and'. A comma is required before the conjunction to separate two independent clauses.","incorrect":[{"choice":"A comma belongs after the word “” hit","reason":"\"A comma belongs after the word “” hit\" does not place the series commas around the list items correctly."},"",{"choice":"A comma belongs after the word “and”","category":"incorrect comma placement","reason":"A comma should never be placed immediately after a coordinating conjunction like 'and' when joining two complete sentences; instead, it should be placed before the conjunction."},{"choice":"This sentence does not need a comma.","category":"missing comma","reason":"Since both sides of the conjunction 'and' contain a subject and a verb (independent clauses), a comma is necessary to clearly signal the start of the second part of the sentence."}]},"studyAid":{"definition":"When you use a coordinating conjunction (like 'and', 'but', or 'or') to connect two complete sentences, you must place a comma before that conjunction.","example":"I went to the store, and I bought bread. It was raining, but we played outside anyway.","strategyClue":"Check if both parts of the sentence have their own subject and verb. If they are both complete sentences on their own, look for the 'bridge' word that connects them and place your punctuation mark before it.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Proficient Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":93,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0108","version":3,"contentHash":"sha256:907a88632ee0752d276cdc6cb0df0b5faa988ad49c699580e3187956d7ea3c69","question":"How should the following sentence be punctuated? She didn’t speak to anyone and nobody spoke to her.","choices":["A comma belongs after the word “anyone”","A comma belongs after the word “nobody”","A comma belongs after the word “spoke”","This sentence does not need a comma."],"correct":0,"explanation":{"correct":"Answer: A comma belongs after the word “anyone”. This is a compound sentence because it contains two independent clauses joined by a coordinating conjunction. You must place a comma before the conjunction 'and' to separate the two complete thoughts.","incorrect":["",{"choice":"A comma belongs after the word “nobody”","category":"misplaced comma","reason":"Placing a comma after 'nobody' incorrectly breaks the second part of the sentence. Commas should only be used to separate two complete, independent sentences joined by a conjunction."},{"choice":"A comma belongs after the word “spoke”","category":"misplaced comma","reason":"Putting a comma after 'spoke' interrupts the middle of the second clause. A comma must always come before the coordinating conjunction, not after it."},{"choice":"This sentence does not need a comma.","category":"missing comma","reason":"Because there are two independent clauses joined by 'and', a comma is required to show the reader where the first thought ends and the second one begins."}]},"studyAid":{"definition":"When joining two independent sentences with a coordinating conjunction (for, and, nor, but, or, yet, so), use a comma before the conjunction.","example":"I like cake, and he likes pie. / She was tired, but she finished her homework.","strategyClue":"Check if there is a complete sentence on both the left side and the right side of the conjunction. If both sides can stand alone as sentences, insert the comma before the connecting word.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Proficient Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":8,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":108,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0112","version":3,"contentHash":"sha256:4aa2d4b178a0c906b63842798322464a2a2670d8c54e400f3f09f2e33d2a3baa","question":"Where in the following sentence would you place a? comma I like cooking new dishes and eating meat but I don’t like washing dishes.","choices":["after the word “and”","before the word “and”","after the word “but","before the word “but”"],"correct":3,"explanation":{"correct":"Answer: before the word “but”. When joining two independent clauses with a coordinating conjunction like 'but', you must place a comma before the conjunction.","incorrect":[{"choice":"after the word “and”","category":"incorrect comma placement","reason":"Placing a comma after 'and' separates the conjunction from the second part of the compound predicate, which is not where the pause occurs in this sentence structure."},{"choice":"before the word “and”","category":"unnecessary comma usage","reason":"In this sentence, 'I like' is the subject and verb for both 'cooking' and 'eating', so no comma is needed before 'and' because these are parts of a compound object, not separate sentences."},{"choice":"after the word “but","category":"incorrect comma placement","reason":"A comma should come before the conjunction to signal a break between two independent thoughts. Placing it after 'but' interrupts the flow of the final clause."},""]},"studyAid":{"definition":"Use a comma before a coordinating conjunction (like and, but, or, so) when it connects two complete sentences (independent clauses).","example":"I want to go, but I am tired. / She played soccer, and he read a book.","strategyClue":"Look at the words on both sides of the conjunction. If both sides could stand alone as complete sentences, you need a comma before the conjunction.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Proficient Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":112,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-commas-series-q0269","version":3,"contentHash":"sha256:cfbebca495394d2ab79580443bac9ddf3b718de7b8a43bf202e6eae1f9031fc6","question":"Choose the sentence that shows correct punctuation.","choices":["The grocery store in Helo Alabama is closed on Tuesdays and Wednesdays.","The grocery store in Helo, Alabama is closed on Tuesdays and Wednesdays.","The grocery store Helo, Alabama is closed on Tuesdays, and Wednesdays. in","The grocery store, in Helo Alabama is closed on Tuesdays and Wednesdays."],"correct":1,"explanation":{"correct":"Answer: The grocery store in Helo, Alabama is closed on Tuesdays and Wednesdays. When writing a city and state together, you must place a comma after the city name and another comma after the state name if the sentence continues.","incorrect":[{"choice":"The grocery store in Helo Alabama is closed on Tuesdays and Wednesdays.","category":"missing comma","reason":"This sentence is missing a comma between the city name 'Helo' and the state name 'Alabama'. A comma is required to separate the two locations."},"",{"choice":"The grocery store Helo, Alabama is closed on Tuesdays, and Wednesdays. in","category":"incorrect word order","reason":"The preposition 'in' and the comma after 'Tuesdays' are misplaced. Placing 'in' after the day makes the sentence difficult to read, and you do not need a comma before 'and' when connecting only two items."},{"choice":"The grocery store, in Helo Alabama is closed on Tuesdays and Wednesdays.","category":"unnecessary punctuation","reason":"Placing a comma after 'store' interrupts the flow of the sentence because it separates the subject from the prepositional phrase that describes it."}]},"studyAid":{"definition":"When writing the name of a city and state in a sentence, always put a comma after the city name. If the sentence continues after the state, put a second comma after the state name as well.","example":"I live in Paris, France, which is beautiful. My cousins live in Seattle, Washington.","strategyClue":"Check for locations in the sentence. Locate the city and state pair and verify that there is a comma separating them and another comma closing the pair if it appears in the middle of a sentence.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-commas-series","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":14,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":269,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
